// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;

    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 unlockTime, uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        amount = bound(amount, 1, 1000 ether);
        // unlockTime deliberately left UNbounded: past timestamps must be clamped by the reference
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (uint256 accUnlockTime, ) = c.Acc(actor);
        assertTrue(accUnlockTime >= block.timestamp, "unlockTime must be clamped to at least now");
    }
}
